pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzz the candidate new owner address. The correct contract must never end up with owner == address(0)
    // after transferOwnership; it should revert if newOwner == address(0). The mutant allows setting owner to 0.
    function testFuzz_property(address newOwner) public {
        // Keep domain wide; no restrictive assumes so fuzzer can try address(0).

        bool ok;
        // call transferOwnership as the current owner (setUp deployed c with owner == address(this))
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: the reference contract never ends up with owner == address(0) after transferOwnership call.
        // For the reference: if newOwner == address(0) the call reverts and owner stays non-zero (address(this)).
        // For the mutant: the call may succeed with newOwner == address(0), causing owner() == address(0) and this assert to fail.
        assertTrue(c.owner() != address(0));
    }
}

