// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // We fuzz the caller address attempting transferOwnership. The reference C only allows the current owner
    // to call transferOwnership; any non-owner call must revert. The mutant may allow a non-owner call to succeed
    // in some circumstances (by permitting owner to be set to zero and thereby breaking the intended access control),
    // so a non-owner caller should never be able to successfully invoke transferOwnership on the reference.
    function testFuzz_property(address caller) public {
        // keep domain wide but avoid trivial current owner (which is address(this) from setUp)
        vm.assume(caller != address(this));

        bool ok;
        // try calling transferOwnership as the fuzzed caller; transferOwnership takes an address argument, supply caller as newOwner
        vm.prank(caller);
        try c.transferOwnership(caller) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert: on the reference contract only the owner (address(this)) may successfully call transferOwnership.
        // Since we pranked from a non-owner (caller != address(this)), the call must fail on the correct contract.
        assertTrue(ok == false);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz the newOwner address; if newOwner==address(0) the reference SHOULD revert and keep owner non-zero,
    // while the mutant will allow setting owner to address(0). We must be owner to call transferOwnership.
    function testFuzz_property(address newOwner) public {
        // keep domain wide
        // ensure msg.sender is current owner (setUp made address(this) the owner)
        // perform the call and observe whether owner() becomes zero
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: in the reference, it's impossible that after transferOwnership returns (ok==true)
        // owner() == address(0) because reference reverts when newOwner==address(0). Thus the property:
        // if the call succeeded, then owner() != address(0).
        // This holds for the correct contract for all inputs, but the mutant (which allows setting owner to zero)
        // will make this assertion fail for some fuzzed newOwner (specifically newOwner==address(0)).
        assertTrue(!(ok && c.owner() == address(0)));
    }
}
